@Service
@RequiredArgsConstructor
public class MonedaAlfaResolver {

    private final MonedaAlfaCatalogo catalogo385;   // WKS-MONEDA-ALFA, cargada en 14700-CARGA-CONV-MONALFA
    private final P131Properties props;

    public void resuelve(AgrupadoRecord r, MovimientoTraducido t) {
        t.libroContable(props.libroContable());            // "CONTABLE  " (X(10), con relleno)
        t.monedaOperativa(r.moneda());
        t.monedaAlfa(catalogo385.alfa(r.moneda())          // Optional<String>
                .filter(a -> !a.isBlank())
                .orElse(props.monedaDesvio()));            // "***"
    }
}

