@Component
public class DepartamentoResolver {

    private static final int CENTRALIZA = 2;           // valor de COPC-IND-CENT / COPCN-IND-CENT

    public void resuelve(AgrupadoRecord r, MovimientoTraducido t) {
        t.sirh(r.sucursal());                          // A01-TRAD-SIRH
        t.centralDesvio(r.centralizadora());           // A01-TRAD-CENTRAL-DES
        String depto;
        if (r.centralizadora() > 0) {
            depto = String.valueOf(r.centralizadora());          // centralizadora explícita
        } else if (t.indCentraliza() == CENTRALIZA) {
            depto = String.valueOf(t.departamentoCatalogo());    // W77-DEPTO del COPC/COPCN
        } else {
            depto = String.valueOf(r.sucursal());                // sucursal del movimiento
        }
        t.departamento(Fixed.numeroEnAlfa(depto, 4, 10));   // 9(004) en X(010): "0123      "
    }
}

@Component
@RequiredArgsConstructor
public class AsientoIdentidad {

    private final P131Properties props;
    private final IntercompanyRepository inte;            // ARCH-INTE

    public void completa(AgrupadoRecord r, MovimientoTraducido t) {
        t.idAsiento(new IdAsiento(
                Fixed.izq(String.valueOf(props.sistema()), 4),   // WKS-SISTEMA-PARAM
                Fixed.izq(props.csi(), 3),                        // W77-CSI
                props.asiento().version(),                        // 1
                "  "));                                           // RESTO = SPACES
        t.tipoTransaccion(props.asiento().tipoTransaccion());     // 10
        t.setId(props.asiento().setId());                         // "BNMEX"
        t.esquemaContable(r.tmEsquema());
        // Línea 7371 comentada: el campo nominal FIDEICOMISO recibe el ÁREA.
        t.fideicomiso(r.area());                                  // 9(004) -> 9(006)
        t.claveEvento(0); t.esquemaDesvio(0);

        if (props.sistemasIntercompany().contains(props.sistema())) {     // 84, 87, 403, 500
            t.intercompanyNum(r.intercompany());
            t.intercompanyAlfa(inte.findById(r.intercompany())
                    .map(Intercompany::unidadNegocio).orElse("     "));   // 20600
        } else {
            t.intercompanyAlfa("     ");
            t.intercompanyNum("00000");
        }
    }
}

